export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout: string;
  /** any extra frontmatter keys pass through to templates */
  extra: Record<string, unknown>;
}

export interface Page {
  /** path of the source file relative to the source dir, e.g. posts/hello.md */
  sourcePath: string;
  /** output path relative to the out dir, e.g. posts/hello.html */
  outPath: string;
  /** site-absolute URL path, e.g. /posts/hello.html */
  urlPath: string;
  frontmatter: Frontmatter;
  /** rendered HTML body (markdown -> html) */
  html: string;
  /** raw markdown body */
  raw: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outDir: string;
  includeDrafts: boolean;
  baseUrl: string;
  siteTitle: string;
  siteDescription: string;
}

export const DEFAULT_CONFIG: SiteConfig = {
  sourceDir: "content",
  templateDir: "templates",
  outDir: "dist-site",
  includeDrafts: false,
  baseUrl: "http://localhost:3000",
  siteTitle: "My Site",
  siteDescription: "",
};

import matter from "gray-matter";
import type { Frontmatter } from "./types.js";

const KNOWN_KEYS = new Set(["title", "date", "tags", "draft", "layout"]);

/** Parse a markdown document with optional YAML frontmatter. */
export function parseFrontmatter(src: string): { frontmatter: Frontmatter; body: string } {
  const { data, content } = matter(src);
  return { frontmatter: normalize(data), body: content };
}

export function normalize(data: Record<string, unknown>): Frontmatter {
  const extra: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(data)) {
    if (!KNOWN_KEYS.has(k)) extra[k] = v;
  }
  return {
    title: typeof data.title === "string" ? data.title : "",
    date: coerceDate(data.date),
    tags: coerceTags(data.tags),
    draft: coerceBool(data.draft),
    layout: typeof data.layout === "string" ? data.layout : "default",
    extra,
  };
}

function coerceDate(v: unknown): Date | null {
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  if (typeof v === "string" || typeof v === "number") {
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function coerceTags(v: unknown): string[] {
  if (Array.isArray(v)) return v.map(String).map((s) => s.trim()).filter(Boolean);
  if (typeof v === "string") {
    return v.split(",").map((s) => s.trim()).filter(Boolean);
  }
  return [];
}

function coerceBool(v: unknown): boolean {
  if (typeof v === "boolean") return v;
  if (typeof v === "string") return v.toLowerCase() === "true";
  return false;
}

import MarkdownIt from "markdown-it";
import hljs from "highlight.js";

const md: MarkdownIt = new MarkdownIt({
  html: true,
  linkify: true,
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      const { value } = hljs.highlight(code, { language: lang, ignoreIllegals: true });
      return `<pre><code class="hljs language-${lang}">${value}</code></pre>`;
    }
    return `<pre><code class="hljs">${md.utils.escapeHtml(code)}</code></pre>`;
  },
});

/** Render markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(src: string): string {
  return md.render(src);
}

import Handlebars from "handlebars";
import fs from "node:fs";
import path from "node:path";

export type Layouts = Map<string, Handlebars.TemplateDelegate>;

export interface TemplateSet {
  hbs: typeof Handlebars;
  layouts: Layouts;
  /** render a page body through the named layout ("default" fallback) */
  renderLayout(name: string, context: Record<string, unknown>): string;
  has(name: string): boolean;
}

/**
 * Template dir convention:
 *   templates/*.hbs          -> layouts (default.hbs, post.hbs, tag.hbs, index.hbs, ...)
 *   templates/partials/*.hbs -> registered as partials by filename
 */
export function loadTemplates(templateDir: string): TemplateSet {
  const hbs = Handlebars.create();
  registerHelpers(hbs);

  const partialsDir = path.join(templateDir, "partials");
  if (fs.existsSync(partialsDir)) {
    for (const f of fs.readdirSync(partialsDir).filter((f) => f.endsWith(".hbs"))) {
      const name = path.basename(f, ".hbs");
      hbs.registerPartial(name, fs.readFileSync(path.join(partialsDir, f), "utf8"));
    }
  }

  const layouts: Layouts = new Map();
  if (fs.existsSync(templateDir)) {
    for (const f of fs.readdirSync(templateDir).filter((f) => f.endsWith(".hbs"))) {
      const name = path.basename(f, ".hbs");
      layouts.set(name, hbs.compile(fs.readFileSync(path.join(templateDir, f), "utf8")));
    }
  }

  return {
    hbs,
    layouts,
    has: (name) => layouts.has(name),
    renderLayout(name, context) {
      const tpl = layouts.get(name) ?? layouts.get("default");
      if (!tpl) throw new Error(`No layout "${name}" and no default.hbs in ${templateDir}`);
      return tpl(context);
    },
  };
}

export function registerHelpers(hbs: typeof Handlebars): void {
  hbs.registerHelper("formatDate", (d: unknown, fmt?: unknown) => {
    const date = d instanceof Date ? d : d ? new Date(String(d)) : null;
    if (!date || isNaN(date.getTime())) return "";
    if (fmt === "iso") return date.toISOString();
    return date.toISOString().slice(0, 10); // YYYY-MM-DD
  });
  hbs.registerHelper("eq", (a: unknown, b: unknown) => a === b);
  hbs.registerHelper("join", (arr: unknown, sep: unknown) =>
    Array.isArray(arr) ? arr.join(typeof sep === "string" ? sep : ", ") : ""
  );
}

import type { Page, SiteConfig } from "./types.js";

export function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

/** Generate an RSS 2.0 feed for the given pages (newest first, max 20). */
export function generateRss(pages: Page[], config: SiteConfig): string {
  const base = config.baseUrl.replace(/\/$/, "");
  const items = [...pages]
    .filter((p) => p.frontmatter.date)
    .sort((a, b) => b.frontmatter.date!.getTime() - a.frontmatter.date!.getTime())
    .slice(0, 20)
    .map((p) => {
      const link = `${base}${p.urlPath}`;
      return [
        "    <item>",
        `      <title>${escapeXml(p.frontmatter.title)}</title>`,
        `      <link>${escapeXml(link)}</link>`,
        `      <guid>${escapeXml(link)}</guid>`,
        `      <pubDate>${p.frontmatter.date!.toUTCString()}</pubDate>`,
        `      <description>${escapeXml(p.html)}</description>`,
        "    </item>",
      ].join("\n");
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(base)}</link>
    <description>${escapeXml(config.siteDescription)}</description>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>
`;
}

import fs from "node:fs";
import path from "node:path";
import { parseFrontmatter } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { loadTemplates, type TemplateSet } from "./templates.js";
import { generateRss } from "./rss.js";
import type { Page, SiteConfig } from "./types.js";

export interface BuildResult {
  pages: Page[];
  tags: Map<string, Page[]>;
  written: string[];
}

/** Recursively list files under dir matching a predicate. */
export function listFiles(dir: string, filter: (f: string) => boolean): string[] {
  const out: string[] = [];
  const walk = (d: string) => {
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      const full = path.join(d, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (filter(entry.name)) out.push(full);
    }
  };
  if (fs.existsSync(dir)) walk(dir);
  return out;
}

/** Load and render one markdown source file into a Page (no layout applied yet). */
export function loadPage(sourceDir: string, absFile: string): Page {
  const rel = path.relative(sourceDir, absFile);
  const src = fs.readFileSync(absFile, "utf8");
  const { frontmatter, body } = parseFrontmatter(src);
  const outPath = rel.replace(/\.md$/i, ".html").split(path.sep).join("/");
  return {
    sourcePath: rel.split(path.sep).join("/"),
    outPath,
    urlPath: "/" + outPath,
    frontmatter,
    html: renderMarkdown(body),
    raw: body,
  };
}

function pageContext(p: Page, config: SiteConfig) {
  return {
    ...p.frontmatter.extra,
    title: p.frontmatter.title,
    date: p.frontmatter.date,
    tags: p.frontmatter.tags,
    draft: p.frontmatter.draft,
    content: p.html, // use {{{content}}} in layouts
    url: p.urlPath,
    site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
  };
}

function writeOut(outDir: string, relPath: string, content: string, written: string[]): void {
  const abs = path.join(outDir, relPath);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, content);
  written.push(relPath);
}

/** Collect pages, honoring the draft flag. */
export function collectPages(config: SiteConfig): Page[] {
  const files = listFiles(config.sourceDir, (f) => f.toLowerCase().endsWith(".md"));
  const pages = files.map((f) => loadPage(config.sourceDir, f));
  return config.includeDrafts ? pages : pages.filter((p) => !p.frontmatter.draft);
}

export function groupByTag(pages: Page[]): Map<string, Page[]> {
  const tags = new Map<string, Page[]>();
  for (const p of pages) {
    for (const t of p.frontmatter.tags) {
      const list = tags.get(t) ?? [];
      list.push(p);
      tags.set(t, list);
    }
  }
  return tags;
}

/** Full site build: pages, tag index pages, index, rss.xml. */
export function buildSite(config: SiteConfig): BuildResult {
  const templates = loadTemplates(config.templateDir);
  const pages = collectPages(config);
  const written: string[] = [];

  const sorted = [...pages].sort(
    (a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0)
  );

  for (const p of pages) {
    written.push(...renderPageToDisk(p, templates, config, sorted));
  }

  // Tag index pages: /tags/<tag>.html
  const tags = groupByTag(pages);
  for (const [tag, tagPages] of tags) {
    const ctx = {
      title: `Tag: ${tag}`,
      tag,
      pages: tagPages.map((p) => pageContext(p, config)),
      site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
    };
    const layout = templates.has("tag") ? "tag" : "default";
    writeOut(config.outDir, `tags/${slugify(tag)}.html`, templates.renderLayout(layout, ctx), written);
  }

  // Site index (if an index.hbs layout exists and no content index.md produced one)
  if (templates.has("index") && !pages.some((p) => p.outPath === "index.html")) {
    const ctx = {
      title: config.siteTitle,
      pages: sorted.map((p) => pageContext(p, config)),
      tags: [...tags.keys()].sort(),
      site: { title: config.siteTitle, description: config.siteDescription, baseUrl: config.baseUrl },
    };
    writeOut(config.outDir, "index.html", templates.renderLayout("index", ctx), written);
  }

  // RSS
  writeOut(config.outDir, "rss.xml", generateRss(pages, config), written);

  return { pages, tags, written };
}

/** Render a single page through its layout and write it. Used by full build and incremental rebuilds. */
export function renderPageToDisk(
  page: Page,
  templates: TemplateSet,
  config: SiteConfig,
  allSorted: Page[]
): string[] {
  const written: string[] = [];
  const ctx = { ...pageContext(page, config), pages: allSorted.map((p) => pageContext(p, config)) };
  writeOut(config.outDir, page.outPath, templates.renderLayout(page.frontmatter.layout, ctx), written);
  return written;
}

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { buildSite } from "./build.js";
import type { SiteConfig } from "./types.js";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css",
  ".js": "text/javascript",
  ".json": "application/json",
  ".xml": "application/xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
};

export const RELOAD_SNIPPET = `<script>
(() => {
  const ws = new WebSocket("ws://" + location.host + "/__livereload");
  ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
  ws.onclose = () => setTimeout(() => location.reload(), 1000);
})();
</script>`;

/** Inject the live-reload script before </body> (or append if absent). */
export function injectReloadScript(html: string): string {
  const i = html.lastIndexOf("</body>");
  if (i === -1) return html + RELOAD_SNIPPET;
  return html.slice(0, i) + RELOAD_SNIPPET + html.slice(i);
}

export interface DevServer {
  close(): Promise<void>;
  port: number;
}

export async function startDevServer(config: SiteConfig, port: number): Promise<DevServer> {
  buildSite(config); // initial build

  const server = http.createServer((req, res) => {
    const urlPath = decodeURIComponent((req.url ?? "/").split("?")[0]);
    let rel = urlPath.endsWith("/") ? urlPath + "index.html" : urlPath;
    let abs = path.join(config.outDir, path.normalize(rel));
    if (!abs.startsWith(path.resolve(config.outDir)) && !abs.startsWith(config.outDir)) {
      res.writeHead(403).end("Forbidden");
      return;
    }
    if (!fs.existsSync(abs) && fs.existsSync(abs + ".html")) abs += ".html";
    if (!fs.existsSync(abs) || fs.statSync(abs).isDirectory()) {
      res.writeHead(404, { "Content-Type": "text/html" }).end(injectReloadScript("<h1>404</h1>"));
      return;
    }
    const ext = path.extname(abs).toLowerCase();
    const type = MIME[ext] ?? "application/octet-stream";
    let body: Buffer | string = fs.readFileSync(abs);
    if (ext === ".html") body = injectReloadScript(body.toString("utf8"));
    res.writeHead(200, { "Content-Type": type }).end(body);
  });

  const wss = new WebSocketServer({ server, path: "/__livereload" });
  const broadcast = () => {
    for (const c of wss.clients) if (c.readyState === WebSocket.OPEN) c.send("reload");
  };

  // Debounced rebuild-on-change. Latency-first: cheap sites rebuild in ms;
  // debounce collapses editor save bursts into one rebuild.
  let timer: NodeJS.Timeout | null = null;
  const scheduleRebuild = (file: string) => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      const t0 = Date.now();
      try {
        buildSite(config);
        console.log(`[ssgen] rebuilt in ${Date.now() - t0}ms (${file})`);
        broadcast();
      } catch (err) {
        console.error("[ssgen] rebuild failed:", err);
      }
    }, 50);
  };

  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });
  watcher.on("all", (_evt, file) => scheduleRebuild(file));

  await new Promise<void>((resolve) => server.listen(port, resolve));
  const actualPort = (server.address() as { port: number }).port;
  console.log(`[ssgen] dev server: http://localhost:${actualPort}`);

  return {
    port: actualPort,
    async close() {
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((e) => (e ? reject(e) : resolve()))
      );
    },
  };
}

#!/usr/bin/env node
import { buildSite } from "./build.js";
import { startDevServer } from "./server.js";
import { DEFAULT_CONFIG, type SiteConfig } from "./types.js";

export interface CliOptions {
  command: "build" | "serve" | "help";
  config: SiteConfig;
  port: number;
}

export const HELP = `ssgen - static site generator

Usage:
  ssgen build [options]   Build the site once
  ssgen serve [options]   Build, serve, and live-reload on changes

Options:
  -s, --source <dir>       Source dir of Markdown files   (default: content)
  -t, --templates <dir>    Handlebars template dir        (default: templates)
  -o, --out <dir>          Output dir                     (default: dist-site)
      --drafts             Include draft: true pages
      --base-url <url>     Absolute base URL for RSS links
      --title <str>        Site title
      --description <str>  Site description
  -p, --port <n>           Dev server port                (default: 3000)
  -h, --help               Show help
`;

/** Parse argv (without node/script prefix). Throws on unknown flags / missing values. */
export function parseArgs(argv: string[]): CliOptions {
  const config: SiteConfig = { ...DEFAULT_CONFIG };
  let command: CliOptions["command"] = "help";
  let port = 3000;

  const args = [...argv];
  const first = args[0];
  if (first === "build" || first === "serve") {
    command = first;
    args.shift();
  } else if (first === "help" || first === "-h" || first === "--help") {
    return { command: "help", config, port };
  } else if (first !== undefined && !first.startsWith("-")) {
    throw new Error(`Unknown command: ${first}`);
  }

  const need = (flag: string): string => {
    const v = args.shift();
    if (v === undefined || v.startsWith("-")) throw new Error(`Missing value for ${flag}`);
    return v;
  };

  while (args.length) {
    const a = args.shift()!;
    switch (a) {
      case "-s": case "--source": config.sourceDir = need(a); break;
      case "-t": case "--templates": config.templateDir = need(a); break;
      case "-o": case "--out": config.outDir = need(a); break;
      case "--drafts": config.includeDrafts = true; break;
      case "--base-url": config.baseUrl = need(a); break;
      case "--title": config.siteTitle = need(a); break;
      case "--description": config.siteDescription = need(a); break;
      case "-p": case "--port": {
        const n = Number(need(a));
        if (!Number.isInteger(n) || n < 0 || n > 65535) throw new Error(`Invalid port: ${n}`);
        port = n;
        break;
      }
      case "-h": case "--help": command = "help"; break;
      default: throw new Error(`Unknown flag: ${a}`);
    }
  }
  return { command, config, port };
}

export async function main(argv: string[]): Promise<number> {
  let opts: CliOptions;
  try {
    opts = parseArgs(argv);
  } catch (err) {
    console.error(String(err instanceof Error ? err.message : err));
    console.error(HELP);
    return 2;
  }

  if (opts.command === "help") {
    console.log(HELP);
    return 0;
  }
  if (opts.command === "build") {
    const t0 = Date.now();
    const { pages, written } = buildSite(opts.config);
    console.log(`[ssgen] ${pages.length} pages, ${written.length} files -> ${opts.config.outDir} in ${Date.now() - t0}ms`);
    return 0;
  }
  await startDevServer(opts.config, opts.port);
  return 0;
}

// Only run when executed directly (not when imported by tests).
if (import.meta.url === `file://${process.argv[1]}`) {
  main(process.argv.slice(2)).then((code) => {
    if (code !== 0) process.exitCode = code;
  });
}

export * from "./types.js";
export * from "./frontmatter.js";
export * from "./markdown.js";
export * from "./templates.js";
export * from "./rss.js";
export * from "./build.js";
export { parseArgs, main, HELP, type CliOptions } from "./cli.js";
export { startDevServer, injectReloadScript, RELOAD_SNIPPET } from "./server.js";

