import { describe, it, expect } from "vitest";
import { parseFrontmatter } from "../src/frontmatter.js";

describe("parseFrontmatter", () => {
  it("parses title, date, tags, draft", () => {
    const { frontmatter, body } = parseFrontmatter(
      `---
title: Hello World
date: 2026-01-15
tags: [ts, web]
draft: true
---
# Body here
`
    );
    expect(frontmatter.title).toBe("Hello World");
    expect(frontmatter.date?.toISOString().slice(0, 10)).toBe("2026-01-15");
    expect(frontmatter.tags).toEqual(["ts", "web"]);
    expect(frontmatter.draft).toBe(true);
    expect(body.trim()).toBe("# Body here");
  });

  it("handles missing frontmatter with sane defaults", () => {
    const { frontmatter, body } = parseFrontmatter("just markdown");
    expect(frontmatter).toMatchObject({ title: "", date: null, tags: [], draft: false, layout: "default" });
    expect(body).toBe("just markdown");
  });

  it("coerces comma-separated tag strings", () => {
    const { frontmatter } = parseFrontmatter(`---\ntags: a, b , c\n---\nx`);
    expect(frontmatter.tags).toEqual(["a", "b", "c"]);
  });

  it("coerces draft strings and defaults to false", () => {
    expect(parseFrontmatter(`---\ndraft: "true"\n---\nx`).frontmatter.draft).toBe(true);
    expect(parseFrontmatter(`---\ndraft: "nope"\n---\nx`).frontmatter.draft).toBe(false);
    expect(parseFrontmatter(`---\ntitle: t\n---\nx`).frontmatter.draft).toBe(false);
  });

  it("returns null for invalid dates", () => {
    expect(parseFrontmatter(`---\ndate: not-a-date\n---\nx`).frontmatter.date).toBeNull();
  });

  it("passes unknown keys through extra", () => {
    const { frontmatter } = parseFrontmatter(`---\ntitle: t\nauthor: Ada\n---\nx`);
    expect(frontmatter.extra).toEqual({ author: "Ada" });
  });

  it("respects custom layout", () => {
    const { frontmatter } = parseFrontmatter(`---\nlayout: post\n---\nx`);
    expect(frontmatter.layout).toBe("post");
  });
});

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { loadTemplates } from "../src/templates.js";

let dir: string;

beforeAll(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), "ssgen-tpl-"));
  fs.mkdirSync(path.join(dir, "partials"));
  fs.writeFileSync(
    path.join(dir, "default.hbs"),
    `<html><head><title>{{title}}</title></head><body>{{> header}}<main>{{{content}}}</main></body></html>`
  );
  fs.writeFileSync(path.join(dir, "post.hbs"), `<article>{{> header}}{{{content}}}<p>{{formatDate date}}</p></article>`);
  fs.writeFileSync(path.join(dir, "partials", "header.hbs"), `<header>{{title}}</header>`);
});

afterAll(() => fs.rmSync(dir, { recursive: true, force: true }));

describe("loadTemplates", () => {
  it("renders a layout with partials and triple-stash content", () => {
    const t = loadTemplates(dir);
    const html = t.renderLayout("default", { title: "Hi", content: "<p>body</p>" });
    expect(html).toContain("<title>Hi</title>");
    expect(html).toContain("<header>Hi</header>");
    expect(html).toContain("<main><p>body</p></main>"); // not escaped
  });

  it("falls back to default layout for unknown names", () => {
    const t = loadTemplates(dir);
    const html = t.renderLayout("nonexistent", { title: "X", content: "" });
    expect(html).toContain("<title>X</title>");
  });

  it("uses named layouts and the formatDate helper", () => {
    const t = loadTemplates(dir);
    const html = t.renderLayout("post", { title: "P", content: "<b>c</b>", date: new Date("2026-02-03T00:00:00Z") });
    expect(html).toContain("<b>c</b>");
    expect(html).toContain("2026-02-03");
  });

  it("escapes HTML in double-stash expressions", () => {
    const t = loadTemplates(dir);
    const html = t.renderLayout("default", { title: "<script>", content: "" });
    expect(html).toContain("&lt;script&gt;");
  });

  it("throws when no default layout exists", () => {
    const empty = fs.mkdtempSync(path.join(os.tmpdir(), "ssgen-empty-"));
    try {
      expect(() => loadTemplates(empty).renderLayout("anything", {})).toThrow(/default/);
    } finally {
      fs.rmSync(empty, { recursive: true, force: true });
    }
  });
});

import { describe, it, expect } from "vitest";
import { parseArgs } from "../src/cli.js";

describe("parseArgs", () => {
  it("defaults to help with no args", () => {
    expect(parseArgs([]).command).toBe("help");
  });

  it("parses build with defaults", () => {
    const o = parseArgs(["build"]);
    expect(o.command).toBe("build");
    expect(o.config.sourceDir).toBe("content");
    expect(o.config.templateDir).toBe("templates");
    expect(o.config.outDir).toBe("dist-site");
    expect(o.config.includeDrafts).toBe(false);
  });

  it("parses long and short flags", () => {
    const o = parseArgs([
      "build", "-s", "src-md", "--templates", "tpl", "-o", "out",
      "--drafts", "--base-url", "https://example.com", "--title", "T", "--description", "D",
    ]);
    expect(o.config).toMatchObject({
      sourceDir: "src-md",
      templateDir: "tpl",
      outDir: "out",
      includeDrafts: true,
      baseUrl: "https://example.com",
      siteTitle: "T",
      siteDescription: "D",
    });
  });

  it("parses serve with port", () => {
    const o = parseArgs(["serve", "-p", "8080"]);
    expect(o.command).toBe("serve");
    expect(o.port).toBe(8080);
  });

  it("rejects invalid port", () => {
    expect(() => parseArgs(["serve", "--port", "99999"])).toThrow(/Invalid port/);
    expect(() => parseArgs(["serve", "--port", "abc"])).toThrow(/Invalid port/);
  });

  it("rejects unknown commands and flags", () => {
    expect(() => parseArgs(["deploy"])).toThrow(/Unknown command/);
    expect(() => parseArgs(["build", "--wat"])).toThrow(/Unknown flag/);
  });

