    expect(() => parseArgs(["build", "--source"])).toThrow(/Missing value/);
    expect(() => parseArgs(["build", "-s", "--drafts"])).toThrow(/Missing value/);
  });

  it("treats -h/--help anywhere as help", () => {
    expect(parseArgs(["--help"]).command).toBe("help");
    expect(parseArgs(["build", "-h"]).command).toBe("help");
  });
});

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { buildSite, slugify } from "../src/build.js";
import { renderMarkdown } from "../src/markdown.js";
import type { SiteConfig } from "../src/types.js";

let root: string;
let config: SiteConfig;

function write(rel: string, content: string) {
  const abs = path.join(root, rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, content);
}

beforeAll(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), "ssgen-build-"));
  config = {
    sourceDir: path.join(root, "content"),
    templateDir: path.join(root, "templates"),
    outDir: path.join(root, "out"),
    includeDrafts: false,
    baseUrl: "https://example.com",
    siteTitle: "Test Site",
    siteDescription: "A test",
  };

  write("templates/default.hbs", `<html><body><h1>{{title}}</h1>{{{content}}}</body></html>`);
  write("templates/tag.hbs", `<ul>{{#each pages}}<li>{{this.title}}</li>{{/each}}</ul>`);
  write("templates/index.hbs", `<div id="idx">{{#each pages}}<a href="{{this.url}}">{{this.title}}</a>{{/each}}</div>`);

  write(
    "content/posts/one.md",
    `---\ntitle: One\ndate: 2026-01-01\ntags: [alpha, beta]\n---\nHello **one**\n\n\`\`\`js\nconst x = 1;\n\`\`\`\n`
  );
  write("content/posts/two.md", `---\ntitle: Two\ndate: 2026-02-01\ntags: [alpha]\n---\nTwo body`);
  write("content/secret.md", `---\ntitle: Secret\ndraft: true\n---\nhidden`);
});

afterAll(() => fs.rmSync(root, { recursive: true, force: true }));

describe("buildSite", () => {
  it("builds pages, excludes drafts, mirrors directory structure", () => {
    const res = buildSite(config);
    expect(res.pages.map((p) => p.frontmatter.title).sort()).toEqual(["One", "Two"]);
    expect(fs.existsSync(path.join(config.outDir, "posts/one.html"))).toBe(true);
    expect(fs.existsSync(path.join(config.outDir, "posts/two.html"))).toBe(true);
    expect(fs.existsSync(path.join(config.outDir, "secret.html"))).toBe(false);
  });

  it("includes drafts with includeDrafts", () => {
    buildSite({ ...config, includeDrafts: true });
    expect(fs.existsSync(path.join(config.outDir, "secret.html"))).toBe(true);
    fs.rmSync(path.join(config.outDir, "secret.html"));
  });

  it("applies layout and highlights code blocks", () => {
    buildSite(config);
    const html = fs.readFileSync(path.join(config.outDir, "posts/one.html"), "utf8");
    expect(html).toContain("<h1>One</h1>");
    expect(html).toContain("<strong>one</strong>");
    expect(html).toContain('class="hljs language-js"');
    expect(html).toContain("hljs-"); // token spans present
  });

  it("generates tag index pages", () => {
    buildSite(config);
    const alpha = fs.readFileSync(path.join(config.outDir, "tags/alpha.html"), "utf8");
    const beta = fs.readFileSync(path.join(config.outDir, "tags/beta.html"), "utf8");
    expect(alpha).toContain("<li>One</li>");
    expect(alpha).toContain("<li>Two</li>");
    expect(beta).toContain("<li>One</li>");
    expect(beta).not.toContain("<li>Two</li>");
  });

  it("generates an index page sorted newest-first", () => {
    buildSite(config);
    const idx = fs.readFileSync(path.join(config.outDir, "index.html"), "utf8");
    expect(idx.indexOf("Two")).toBeLessThan(idx.indexOf("One"));
    expect(idx).toContain('href="/posts/one.html"');
  });

  it("generates a valid RSS feed with absolute links, newest first", () => {
    buildSite(config);
    const rss = fs.readFileSync(path.join(config.outDir, "rss.xml"), "utf8");
    expect(rss).toContain("<rss version=\"2.0\">");
    expect(rss).toContain("<title>Test Site</title>");
    expect(rss).toContain("https://example.com/posts/one.html");
    expect(rss.indexOf("<title>Two</title>")).toBeLessThan(rss.indexOf("<title>One</title>"));
    expect(rss).not.toContain("Secret");
  });
});

describe("renderMarkdown", () => {
  it("escapes unhighlighted fences and renders inline markdown", () => {
    const html = renderMarkdown("```\n<b>raw</b>\n```\n\n*em*");
    expect(html).toContain("&lt;b&gt;raw&lt;/b&gt;");
    expect(html).toContain("<em>em</em>");
  });
});

describe("slugify", () => {
  it("normalizes tags to url-safe slugs", () => {
    expect(slugify("C++ / Systems")).toBe("c-systems");
    expect(slugify("  Web Dev  ")).toBe("web-dev");
  });
});

import { describe, it, expect } from "vitest";
import { generateRss, escapeXml } from "../src/rss.js";
import type { Page, SiteConfig } from "../src/types.js";

const config: SiteConfig = {
  sourceDir: "c",
  templateDir: "t",
  outDir: "o",
  includeDrafts: false,
  baseUrl: "https://site.test/",
  siteTitle: "Feed & Co",
  siteDescription: "desc",
};

function page(title: string, date: string | null, urlPath: string): Page {
  return {
    sourcePath: "x.md",
    outPath: urlPath.slice(1),
    urlPath,
    raw: "",
    html: `<p>${title}</p>`,
    frontmatter: { title, date: date ? new Date(date) : null, tags: [], draft: false, layout: "default", extra: {} },
  };
}

describe("generateRss", () => {
  it("escapes XML entities in channel and items", () => {
    const rss = generateRss([page("A & B <ok>", "2026-01-01", "/a.html")], config);
    expect(rss).toContain("<title>Feed &amp; Co</title>");
    expect(rss).toContain("A &amp; B &lt;ok&gt;");
    expect(rss).toContain("&lt;p&gt;");
  });

  it("skips undated pages and strips trailing slash from base URL", () => {
    const rss = generateRss([page("Dated", "2026-01-01", "/d.html"), page("Undated", null, "/u.html")], config);
    expect(rss).toContain("https://site.test/d.html");
    expect(rss).not.toContain("Undated");
    expect(rss).not.toContain("site.test//");
  });

  it("caps at 20 items, newest first", () => {
    const pages = Array.from({ length: 25 }, (_, i) =>
      page(`P${i}`, `2026-01-${String(i + 1).padStart(2, "0")}`, `/p${i}.html`)
    );
    const rss = generateRss(pages, config);
    expect((rss.match(/<item>/g) ?? []).length).toBe(20);
    expect(rss).toContain("P24"); // newest kept
    expect(rss).not.toContain("<title>P0</title>"); // oldest dropped
  });

  it("escapeXml handles all five entities", () => {
    expect(escapeXml(`&<>"'`)).toBe("&amp;&lt;&gt;&quot;&apos;");
  });
});

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { injectReloadScript, RELOAD_SNIPPET, startDevServer } from "../src/server.js";
import type { SiteConfig } from "../src/types.js";
import type { DevServer } from "../src/server.js";
import WebSocket from "ws";

describe("injectReloadScript", () => {
  it("injects before </body>", () => {
    const out = injectReloadScript("<html><body><p>x</p></body></html>");
    expect(out.indexOf(RELOAD_SNIPPET)).toBeLessThan(out.indexOf("</body>"));
    expect(out).toContain("__livereload");
  });

  it("appends when no </body> exists", () => {
    expect(injectReloadScript("<p>x</p>")).toBe("<p>x</p>" + RELOAD_SNIPPET);
  });
});

describe("dev server", () => {
  let root: string;
  let server: DevServer;
  let config: SiteConfig;

  beforeAll(async () => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), "ssgen-srv-"));
    config = {
      sourceDir: path.join(root, "content"),
      templateDir: path.join(root, "templates"),
      outDir: path.join(root, "out"),
      includeDrafts: false,
      baseUrl: "http://localhost",
      siteTitle: "S",
      siteDescription: "",
    };
    fs.mkdirSync(config.sourceDir, { recursive: true });
    fs.mkdirSync(config.templateDir, { recursive: true });
    fs.writeFileSync(path.join(config.templateDir, "default.hbs"), `<html><body>{{{content}}}</body></html>`);
    fs.writeFileSync(path.join(config.sourceDir, "a.md"), `---\ntitle: A\ndate: 2026-01-01\n---\nHello A`);
    server = await startDevServer(config, 0); // ephemeral port
  }, 15000);

  afterAll(async () => {
    await server?.close();
    fs.rmSync(root, { recursive: true, force: true });
  });

  it("serves built HTML with the reload script injected", async () => {
    const res = await fetch(`http://localhost:${server.port}/a.html`);
    expect(res.status).toBe(200);
    const body = await res.text();
    expect(body).toContain("Hello A");
    expect(body).toContain("__livereload");
  });

  it("404s unknown paths (with reload script so the page can recover)", async () => {
    const res = await fetch(`http://localhost:${server.port}/nope.html`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain("__livereload");
  });

  it("broadcasts reload over WebSocket when a source file changes", async () => {
    const ws = new WebSocket(`ws://localhost:${server.port}/__livereload`);
    await new Promise((resolve, reject) => {
      ws.once("open", resolve);
      ws.once("error", reject);
    });
    const msg = new Promise<string>((resolve, reject) => {
      const t = setTimeout(() => reject(new Error("no reload message within 10s")), 10000);
      ws.once("message", (d) => {
        clearTimeout(t);
        resolve(d.toString());
      });
    });
    fs.writeFileSync(path.join(config.sourceDir, "a.md"), `---\ntitle: A\ndate: 2026-01-01\n---\nHello EDITED`);
    expect(await msg).toBe("reload");
    ws.close();

    // rebuilt content is served
    const body = await (await fetch(`http://localhost:${server.port}/a.html`)).text();
    expect(body).toContain("Hello EDITED");
  }, 15000);
});
